"""Generated by the tkinter-ui skill (web look)."""
import os
import sys
from pathlib import Path

candidates = [os.environ.get("TKUI_TKWEBUI_PATH"),
              Path(__file__).resolve().parent / "tkwebui-main",
              Path.cwd() / "tkwebui-main"]
for candidate in candidates:
    if not candidate:
        continue
    candidate = Path(candidate)
    if (candidate / "tkwebui" / "__init__.py").is_file():
        sys.path.insert(0, str(candidate))
        break

import tkinter as tk
from tkinter import ttk
import tkwebui as UI


def main():
    UI.enable_dpi_awareness()
    root = tk.Tk()
    root.title('TkUI Dashboard')
    root.geometry("1000x700")
    UI.apply_theme(root)

    frame = ttk.Frame(root, padding=24)
    frame.pack(fill="both", expand=True)
    ttk.Label(frame, text="Overview",
              font=("Microsoft YaHei UI", 16, "bold")).pack(anchor="w")
    ttk.Label(frame, text="Recent activity",
              style="Muted.TLabel").pack(anchor="w", pady=(4, 16))
    stats = ttk.Frame(frame)
    stats.pack(fill="x", pady=(0, 14))
    for label, value, delta, kind in (
            ("Active", "8", "+2", "info"),
            ("Done", "24", "+12%", "success"),
            ("Risk", "3", "-1", "warning")):
        card = UI.Card(stats)
        card.pack(side="left", fill="both", expand=True, padx=(0, 10))
        ttk.Label(card, text=label, style="Muted.TLabel").pack(anchor="w")
        ttk.Label(card, text=value,
                  font=("Microsoft YaHei UI", 22, "bold")).pack(anchor="w")
        UI.Badge(card, text=delta, kind=kind).pack(anchor="w", pady=(4, 0))
    UI.LineChart(frame, values=[12, 18, 14, 26, 23],
                 labels=["Mon", "Tue", "Wed", "Thu", "Fri"],
                 height=190).pack(fill="x", pady=(0, 12))
    UI.DataTable(frame, columns=["Task", "Owner", "Status"],
                 rows=[["Review", "Mia", "Doing"], ["Audit", "Ken", "Done"]],
                 page_size=8, height=5).pack(fill="both", expand=True)

    root.mainloop()


if __name__ == "__main__":
    main()
